# Inject the clock and the sleeper so time-based code is deterministic.
class FakeClock:
    def __init__(self, t): self.t = t
    def now(self): return self.t
    def sleep(self, s): self.t += s      # "sleeping" just moves time

def is_expired(token_expiry, clock):
    return clock.now() >= token_expiry

def retry(op, clock, attempts=4, base=1.0):
    for i in range(attempts):
        try:
            return op()
        except RuntimeError:
            if i == attempts - 1:
                raise
            clock.sleep(base * 2 ** i)    # 1s, 2s, 4s backoff

clock = FakeClock(1000)
print("expired at t=1000:", is_expired(1060, clock))
clock.t = 1060
print("expired at t=1060:", is_expired(1060, clock))

calls = []
def flaky():
    calls.append(clock.now())
    if len(calls) < 4:
        raise RuntimeError("down")
    return "ok"

clock.t = 0
print("result:", retry(flaky, clock))
print("attempt times:", calls)            # [0, 1.0, 3.0, 7.0], no real waiting

# Consumer-driven contract: consumer states needs, provider replays them.
contract = {                              # written by the consumer's tests
    "request": {"method": "GET", "path": "/users/7"},
    "status": 200,
    "body_types": {"id": int, "email": str},
}

def provider_v1(method, path):
    return 200, {"id": 7, "email": "a@x.test", "name": "Ann"}

def provider_v2(method, path):            # renamed email -> mail
    return 200, {"id": 7, "mail": "a@x.test", "name": "Ann"}

def verify(provider, c):
    status, body = provider(c["request"]["method"], c["request"]["path"])
    errors = []
    if status != c["status"]:
        errors.append("status " + str(status))
    for field, typ in c["body_types"].items():
        if field not in body:
            errors.append("missing field " + field)
        elif not isinstance(body[field], typ):
            errors.append("wrong type for " + field)
    return errors                         # extra fields (name) are fine

for name, p in (("v1", provider_v1), ("v2", provider_v2)):
    errs = verify(p, contract)
    print(name, "OK" if not errs else "BREAKS consumer: " + ", ".join(errs))

# Hexagonal: the core owns the port; adapters plug in from outside.
class OrderService:                       # core / use case
    def __init__(self, repo, notifier):
        self.repo, self.notifier = repo, notifier   # outbound ports

    def place(self, order_id, qty):
        if qty <= 0:
            raise ValueError("qty must be positive")  # business rule
        self.repo.save(order_id, qty)
        self.notifier.notify("order " + order_id + " x" + str(qty))
        return order_id

class InMemoryRepo:                       # adapter 1 (tests)
    def __init__(self): self.data = {}
    def save(self, k, v): self.data[k] = v

class FileLikeRepo:                       # adapter 2 (stands in for a DB)
    def __init__(self): self.lines = []
    def save(self, k, v): self.lines.append(k + "," + str(v))

class ConsoleNotifier:
    def notify(self, msg): print("notify:", msg)

for repo in (InMemoryRepo(), FileLikeRepo()):
    svc = OrderService(repo, ConsoleNotifier())   # same core, other adapter
    svc.place("A1", 3)
    print(type(repo).__name__, "->", vars(repo))
try:
    OrderService(InMemoryRepo(), ConsoleNotifier()).place("A2", 0)
except ValueError as e:
    print("rejected:", e)

# Tiny mutation test: change the code, see whether any test notices.
SRC = "def can_vote(age): return age >= 18"
MUTANTS = [SRC.replace(">=", ">"), SRC.replace("18", "19"), SRC.replace(">=", "<")]

def run_tests(src, tests):
    env = {}
    exec(src, env)                        # load the (mutated) function
    return all(env["can_vote"](a) == want for a, want in tests)

weak = [(30, True), (5, False)]           # line coverage 100%, weak asserts
strong = weak + [(18, True), (17, False)] # adds the boundary

for label, tests in (("weak", weak), ("strong", strong)):
    print(label, "suite passes on original:", run_tests(SRC, tests))
    killed = sum(not run_tests(m, tests) for m in MUTANTS)
    print(label, "mutants killed: %d of %d" % (killed, len(MUTANTS)))
    for m in MUTANTS:
        if run_tests(m, tests):
            print("  survived:", m)
